import{_ as t,o as s,c as i,a4 as a}from"./chunks/framework.bruR1JhL.js";const k=JSON.parse('{"title":"Build from source","description":"Set up a development copy of Tilepress, run it with hot reload, run the tests, and build the exe and the MSI installer.","frontmatter":{"title":"Build from source","description":"Set up a development copy of Tilepress, run it with hot reload, run the tests, and build the exe and the MSI installer."},"headers":[],"relativePath":"docs/build.md","filePath":"docs/build.md","lastUpdated":1795509372000}'),o={name:"docs/build.md"};function d(n,e,l,r,c,h){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h1><p>Tilepress is a desktop app with a <strong>React</strong> and TypeScript interface (built with Vite) and <strong>Python</strong> business logic. <a href="https://pywebview.flowrl.com/" target="_blank" rel="noreferrer">pywebview</a> opens a native window with the WebView2 runtime built into Windows and lets the interface call Python methods directly. <strong>PyInstaller</strong> bundles Python, the backend and the built interface into <code>Tilepress.exe</code>, and the <strong>WiX Toolset</strong> packs that into an MSI.</p><p>Tilepress is free software under the GNU GPL, version 3 or later. Before you send a change, read <a href="https://github.com/epicabdou/tilepress/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Windows 10 or 11, 64-bit. Several features use Windows itself (Office automation, Windows OCR, face detection, printing).</li><li>Python 3.11 or later.</li><li>Node.js 20 or later.</li><li>The .NET SDK 6 or later, only to build the <code>.msi</code> installer.</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Get the code:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">epicabdou</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tilepress.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd tilepress</span></span></code></pre></div><p>Create a virtual environment and install the Python and frontend dependencies:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m venv .venv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pip install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r requirements</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dev.txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prefix frontend install</span></span></code></pre></div><h2 id="run-in-development" tabindex="-1">Run in development <a class="header-anchor" href="#run-in-development" aria-label="Permalink to &quot;Run in development&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python scripts\\dev.py</span></span></code></pre></div><p>This starts the Vite dev server on <code>127.0.0.1:5173</code> and opens the app window pointed at it.</p><ul><li>React changes reload straight away.</li><li>After changing Python, close the window and run the command again.</li><li>DevTools are on in development: right-click and choose <strong>Inspect</strong>.</li><li>Closing the window stops Vite.</li><li>Extra flags are passed to the app, for example <code>scripts\\dev.py --self-test</code>.</li></ul><p>If you open <code>http://127.0.0.1:5173</code> in an ordinary browser, you see the interface, but it can&#39;t reach Python: the status button says <strong>No Python backend</strong>.</p><p><code>backend\\main.py</code> is the entry point, both from source and in the packaged build. It accepts <code>--dev</code> (load the interface from the Vite server), <code>--debug</code> (turn on DevTools) and <code>--self-test</code> (see <a href="#tests">Tests</a>).</p><h2 id="build-the-app" tabindex="-1">Build the app <a class="header-anchor" href="#build-the-app" aria-label="Permalink to &quot;Build the app&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python scripts\\build.py</span></span></code></pre></div><p>This builds the React app, then runs PyInstaller. The result is <code>dist\\Tilepress\\Tilepress.exe</code>, a folder build that starts fastest. Zip the <code>dist\\Tilepress</code> folder to hand it out. The licence and third-party notices are copied next to the exe.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python scripts\\build.py </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">onefile</span></span></code></pre></div><p>This makes a single <code>dist\\Tilepress.exe</code> instead. It&#39;s easier to pass around, but it starts more slowly, because it unpacks itself to a temporary folder on every launch.</p><h2 id="build-the-msi-installer" tabindex="-1">Build the MSI installer <a class="header-anchor" href="#build-the-msi-installer" aria-label="Permalink to &quot;Build the MSI installer&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python scripts\\build.py </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msi</span></span></code></pre></div><p>This builds the folder version, packs it into <code>dist\\Tilepress-&lt;version&gt;-x64.msi</code> (about 75 MB), and runs Windows Installer&#39;s consistency checks on it. Add <code>--skip-app</code> to repack the existing <code>dist\\Tilepress</code> folder without rebuilding it. <code>--msi</code> can&#39;t be combined with <code>--onefile</code>.</p><ul><li><strong>Tooling:</strong> WiX Toolset 5.0.2 is pinned in <code>dotnet-tools.json</code> and restored automatically; it needs the .NET SDK. The project stays on WiX 5 because WiX 6 and later require accepting the Open Source Maintenance Fee EULA.</li><li><strong>Sources:</strong> <code>installer\\Tilepress.wxs</code> describes the package, files and Start menu shortcut. <code>installer\\TilepressUI.wxs</code> has the dialogs: Welcome, Ready to install and Finish, with no licence page.</li><li><strong>Artwork:</strong> the installer images in <code>assets\\installer\\</code> and the app icon <code>assets\\icon.ico</code> are generated by <code>scripts\\make_brand.py</code>. Edit that script and run <code>.venv\\Scripts\\python scripts\\make_brand.py</code> to regenerate them.</li><li><strong>New version:</strong> bump <code>__version__</code> in <code>backend\\toolbox\\__init__.py</code> and build again. A newer MSI replaces the installed version; an older one refuses to install over a newer one.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never change the <code>UpgradeCode</code> in <code>installer\\Tilepress.wxs</code>. It&#39;s how Windows knows a new MSI is an upgrade of the same product. If it changes, versions install side by side.</p></div><p>The installer is per-user by default (<code>%LocalAppData%\\Programs\\Tilepress</code>, no admin prompt). Run it elevated with <code>ALLUSERS=1</code> to install for everyone in Program Files. See <a href="/tilepress/docs/">Getting started</a> for the user&#39;s side.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest</span></span></code></pre></div><p>The unit tests in <code>backend\\tests</code> cover the business logic in <code>backend\\toolbox\\services</code>.</p><p>The tests that start Microsoft Office or LibreOffice are slow, so they&#39;re skipped by default. To run them:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOOLBOX_OFFICE_TESTS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; .venv\\Scripts\\python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_convert.py</span></span></code></pre></div><p>The image AI tests use small stand-in models, to check tiling, masking and the checksum-verified download. To run them with the real models, point <code>TOOLBOX_AI_MODELS</code> at a models folder, such as the app&#39;s own:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOOLBOX_AI_MODELS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOCALAPPDATA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\Tilepress\\models&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; .venv\\Scripts\\python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_images.py</span></span></code></pre></div><p>The frontend has a linter:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prefix frontend run lint</span></span></code></pre></div><h3 id="the-self-test" tabindex="-1">The self-test <a class="header-anchor" href="#the-self-test" aria-label="Permalink to &quot;The self-test&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dist\\Tilepress\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Tilepress.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">self</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test</span></span></code></pre></div><p>The self-test checks the whole stack, which catches a packaged build that&#39;s missing a library or its data files:</p><ol><li>It renders a PDF page with PDFium.</li><li>It opens the real window and waits until the interface has connected to Python and the Explorer has listed its first folder.</li><li>It prints Markdown with code highlighting to PDF through WebView2, converts an image, and loads the Office automation modules (without starting Office).</li><li>It runs the PDF tools on a small generated PDF (to Word, PowerPoint, Excel and Markdown, watermark, protect, compress, booklet layout, and a digital signature that it then verifies) and loads the Windows OCR modules. Then it runs the image tools on generated pictures (HEIC, WebP and AVIF, resize, the editor with text and a filter, a watermark, the Windows face detector) and loads ONNX Runtime.</li><li>It exits with code <code>0</code> on success and <code>1</code> on failure.</li></ol><p>It works with <code>backend\\main.py</code>, <code>scripts\\dev.py</code> and packaged builds, so you can use it in CI.</p><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What&#39;s there</th></tr></thead><tbody><tr><td><code>backend\\main.py</code></td><td>Entry point, from source and for PyInstaller</td></tr><tr><td><code>backend\\toolbox\\app.py</code></td><td>Creates the window, picks the dev or built URL, runs <code>--self-test</code></td></tr><tr><td><code>backend\\toolbox\\api.py</code></td><td>The methods the interface can call (<code>window.pywebview.api</code>)</td></tr><tr><td><code>backend\\toolbox\\paths.py</code></td><td>Source vs. packaged paths, and the per-user data folder</td></tr><tr><td><code>backend\\toolbox\\html_print.py</code></td><td>HTML to PDF and HTML to Image, with WebView2 in a hidden window</td></tr><tr><td><code>backend\\toolbox\\services\\</code></td><td>The business logic, with no UI imports and unit-tested: <code>pdf\\</code>, <code>convert\\</code>, <code>frompdf\\</code>, <code>editing\\</code>, <code>security\\</code>, <code>printing\\</code>, <code>images\\</code>, <code>latex.py</code>, <code>components.py</code> (the Tectonic download), <code>history.py</code>, <code>settings.py</code>, <code>filesystem.py</code>, <code>preview.py</code></td></tr><tr><td><code>backend\\tests\\</code></td><td>The tests</td></tr><tr><td><code>frontend\\src\\lib\\bridge.ts</code></td><td>Typed wrapper around <code>window.pywebview.api</code></td></tr><tr><td><code>frontend\\src\\lib\\workspace.ts</code></td><td>Shared selection and &quot;open this file in tool X&quot;</td></tr><tr><td><code>frontend\\src\\tools\\registry.tsx</code></td><td>Categories and tools; the navigation and Find a tool are built from it</td></tr><tr><td><code>frontend\\src\\browser\\</code>, <code>frontend\\src\\preview\\</code></td><td>The Explorer and the Preview pane</td></tr><tr><td><code>frontend\\src\\components\\</code></td><td>Shared UI: Find a tool, the status panel, History, menus, icons</td></tr><tr><td><code>frontend\\src\\pdf\\</code>, <code>convert\\</code>, <code>frompdf\\</code>, <code>editing\\</code>, <code>security\\</code>, <code>print\\</code>, <code>latex\\</code>, <code>images\\</code></td><td>The tools, one folder per area</td></tr><tr><td><code>scripts\\</code></td><td><code>dev.py</code>, <code>build.py</code>, <code>make_brand.py</code></td></tr><tr><td><code>installer\\</code></td><td>The WiX sources for the MSI</td></tr><tr><td><code>assets\\</code></td><td>The app icon and the installer artwork</td></tr></tbody></table><p>The Python package and some internal names (<code>toolbox</code>, the <code>TOOLBOX_*</code> variables, storage keys) keep the app&#39;s old name on purpose: renaming them would break saved state. The product name lives in <code>APP_NAME</code> in <code>backend\\toolbox\\__init__.py</code> and in <code>frontend\\src\\brand.ts</code>.</p><h2 id="adding-a-feature" tabindex="-1">Adding a feature <a class="header-anchor" href="#adding-a-feature" aria-label="Permalink to &quot;Adding a feature&quot;">​</a></h2><ol><li>Write the logic in <code>backend\\toolbox\\services\\</code> and add tests.</li><li>Expose it as a public method on <code>Api</code> in <code>backend\\toolbox\\api.py</code>. Return JSON-serialisable values; a raised exception rejects the JavaScript promise with its message. If the method writes files, decorate it with <code>@_records(&quot;&lt;tool name&gt;&quot;)</code> so its runs appear in the <a href="/tilepress/docs/history">History</a>. Name its source argument <code>path</code>, <code>paths</code> or <code>items</code> and return <code>{path, ...}</code>, <code>{files: [...]}</code> or a list of those, and the inputs and outputs are picked up automatically. Tool options are never recorded.</li><li>Add the method&#39;s signature to <code>PyApi</code> in <code>frontend\\src\\lib\\bridge.ts</code>.</li><li>Call it from React with <code>await call(&#39;your_method&#39;, arg1, arg2)</code>.</li><li>For a new screen, add a component and register it under a category in <code>frontend\\src\\tools\\registry.tsx</code>, with an icon and a one-line <code>hint</code> (shown in Find a tool). For a new category, add its id to <code>CategoryId</code> in <code>src\\lib\\workspace.ts</code>, then add an entry to <code>CATEGORIES</code> with its <code>short</code> tab name and icon.</li><li>Style it with the shared classes (<code>card</code>, <code>btn btn-primary</code> / <code>btn-secondary</code> / <code>btn-ghost</code>, <code>text-input</code>, <code>segmented</code>, <code>side-panel</code>, <code>action-bar</code>) and the colour tokens in <code>src\\index.css</code> (<code>--glass</code>, <code>--bg-elev</code>, <code>--field</code>, <code>--accent</code>, <code>--accent-grad</code>…), so it works in the light and dark themes. Pop-ups that use <code>position: fixed</code> must be rendered through a portal, as <code>ContextMenu</code> is; inside a frosted panel they would be clipped.</li><li>To work with files from the Explorer, read the selected item with <code>useWorkspace().selected</code>, accept &quot;open in this tool&quot; requests with <code>useToolRequest(&#39;&lt;tool id&gt;&#39;, path =&gt; …)</code>, and add a matching entry to the file context menu in <code>src\\browser\\FileBrowser.tsx</code>.</li></ol><p>Calls from JavaScript run on pywebview worker threads, so slow work doesn&#39;t freeze the window. Show a busy state in the interface while you wait.</p>`,47)])])}const u=t(o,[["render",d]]);export{k as __pageData,u as default};
